        projected_second = 0.0

    variance = projected_second - projected_mean * projected_mean
    if variance < 0.0:
        variance = 0.0

    certainty_equivalent = projected_mean + RISK * variance ** 0.5
    gap = S - certainty_equivalent

    if gap <= 0.0:
        q = 0.0
    elif gap <= C:
        q = GAIN * gap
    else:
        q = GAIN * C + TAIL * (gap - C)

    if not (q >= 0.0 and q < 1.0e100):
        q = 0.0
    if q > 1000000.0:
        q = 1000000.0
    return float(q)

