                        x[m - 1] = x[m - 1] + arrival

                    for group_index in range(2):
                        if means[group_index] > 0.0:
                            p1 = p1s[group_index]
                            p2 = p2s[group_index]
                            r1 = r1s[group_index]
                            r2 = r2s[group_index]
                            weight1 = w1s[group_index]
                            cumulative = 0.0

                            for step in range(m):
                                if group_index == 0:
