                                    * (h20 + frac0 * r2 ** (n0 + 1))
                                )

                                n1 = int(upper)
                                frac1 = upper - n1
                                if n1 > 0:
                                    h11 = r1 * (1.0 - r1 ** n1) / p1
                                    h21 = r2 * (1.0 - r2 ** n1) / p2
                                else:
                                    h11 = 0.0
                                    h21 = 0.0
                                expected1 = (
                                    weight1 * (h11 + frac1 * r1 ** (n1 + 1))
                                    + (1.0 - weight1)
                                    * (h21 + frac1 * r2 ** (n1 + 1))
                                )

                                depletion = K * (expected1 - expected0)
                                if depletion < 0.0:
                                    depletion = 0.0
                                if depletion > layer:
                                    depletion = layer

                                x[idx] = layer - depletion
                                cumulative = upper

                    for i in range(m - 1):
                        x[i] = x[i + 1]
                    x[m - 1] = 0.0

                freshness_effect = 0.0
                for i in range(m):
                    freshness = (i + 1.0) / m
                    layer_weight = (
                        FRESH_FLOOR
                        + (1.0 - FRESH_FLOOR) * freshness ** A
                    )
                    if layer_weight < 0.0:
                        layer_weight = 0.0
                    freshness_effect = freshness_effect + layer_weight * x[i]

                z = [0.0] * m
                for i in range(m):
                    z[i] = x[i]

                sellthrough_effect = 0.0
                for future_period in range(m):
                    for group_index in range(2):
                        if means[group_index] > 0.0:
                            p1 = p1s[group_index]
                            p2 = p2s[group_index]
                            r1 = r1s[group_index]
                            r2 = r2s[group_index]
                            weight1 = w1s[group_index]
                            cumulative = 0.0

                            for step in range(m):
                                if group_index == 0:
