                                frac0 = lower - n0
                                if n0 > 0:
                                    h10 = r1 * (1.0 - r1 ** n0) / p1
                                    h20 = r2 * (1.0 - r2 ** n0) / p2
                                else:
                                    h10 = 0.0
                                    h20 = 0.0
                                expected0 = (
