                                z[idx] = layer - depletion
                                sellthrough_effect = sellthrough_effect + depletion
                                cumulative = upper

                    for i in range(m - 1):
                        z[i] = z[i + 1]
                    z[m - 1] = 0.0

                effective = (
                    (1.0 - SELL_BLEND) * freshness_effect
                    + SELL_BLEND * sellthrough_effect
                )

                projected_mean = (
                    projected_mean + scenario_probability * effective
                )
                projected_second = (
                    projected_second
                    + scenario_probability * effective * effective
                )
                probability_total = probability_total + scenario_probability

    if probability_total > 0.0:
        projected_mean = projected_mean / probability_total
        projected_second = projected_second / probability_total
    else:
